begin;

set check_function_bodies = false;
set search_path = public, extensions;

ALTER TABLE ONLY public.areas ADD CONSTRAINT areas_pkey PRIMARY KEY (area_id);
ALTER TABLE ONLY public.audit_records ADD CONSTRAINT audit_records_pkey PRIMARY KEY (audit_id);
ALTER TABLE ONLY public.claims ADD CONSTRAINT claims_pkey PRIMARY KEY (claim_id);
ALTER TABLE ONLY public.data_rahasia ADD CONSTRAINT data_rahasia_pkey PRIMARY KEY (secret_id);
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_pkey PRIMARY KEY (found_id);
ALTER TABLE ONLY public.handover_schedules ADD CONSTRAINT handover_schedules_pkey PRIMARY KEY (schedule_id);
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_pkey PRIMARY KEY (lost_id);
ALTER TABLE ONLY public.notifications ADD CONSTRAINT notifications_pkey PRIMARY KEY (notification_id);
ALTER TABLE ONLY public.outbox_surel ADD CONSTRAINT outbox_surel_pkey PRIMARY KEY (outbox_id);
ALTER TABLE ONLY public.penugasan_admin ADD CONSTRAINT penugasan_admin_pkey PRIMARY KEY (assignment_id);
ALTER TABLE ONLY public.photos ADD CONSTRAINT photos_pkey PRIMARY KEY (photo_id);
ALTER TABLE ONLY public.users ADD CONSTRAINT users_pkey PRIMARY KEY (user_id);
ALTER TABLE ONLY public.data_rahasia ADD CONSTRAINT data_rahasia_found_id_key UNIQUE (found_id);
ALTER TABLE ONLY public.areas ADD CONSTRAINT areas_fakultas_check CHECK ((((jenis_area = 'fakultas'::text) AND (fakultas_id IS NOT NULL)) OR ((jenis_area = 'umum'::text) AND (fakultas_id IS NULL))));
ALTER TABLE ONLY public.areas ADD CONSTRAINT areas_jenis_area_check CHECK ((jenis_area = ANY (ARRAY['fakultas'::text, 'umum'::text])));
ALTER TABLE ONLY public.areas ADD CONSTRAINT areas_nama_area_check CHECK (((char_length(btrim(nama_area)) >= 1) AND (char_length(btrim(nama_area)) <= 100)));
ALTER TABLE ONLY public.claims ADD CONSTRAINT claims_alasan_check CHECK (((alasan IS NULL) OR (char_length(alasan) <= 1000)));
ALTER TABLE ONLY public.claims ADD CONSTRAINT claims_approved_match_check CHECK (((status <> 'disetujui'::text) OR (COALESCE(cardinality(ciri_cocok), 0) >= 1)));
ALTER TABLE ONLY public.claims ADD CONSTRAINT claims_ciri_kepemilikan_check CHECK (((char_length(btrim(ciri_kepemilikan)) >= 3) AND (char_length(btrim(ciri_kepemilikan)) <= 1000)));
ALTER TABLE ONLY public.claims ADD CONSTRAINT claims_status_check CHECK ((status = ANY (ARRAY['menunggu'::text, 'disetujui'::text, 'ditolak'::text, 'dibatalkan'::text, 'selesai'::text])));
ALTER TABLE ONLY public.data_rahasia ADD CONSTRAINT data_rahasia_ciri_rahasia_check CHECK (ciri_rahasia_valid(ciri_rahasia));
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_deskripsi_check CHECK (((char_length(btrim(deskripsi)) >= 10) AND (char_length(btrim(deskripsi)) <= 2000)));
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_kategori_check CHECK (((char_length(btrim(kategori)) >= 1) AND (char_length(btrim(kategori)) <= 100)));
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_lokasi_temuan_check CHECK (((char_length(btrim(lokasi_temuan)) >= 1) AND (char_length(btrim(lokasi_temuan)) <= 200)));
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_merek_check CHECK (((merek IS NULL) OR (char_length(merek) <= 100)));
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_status_check CHECK ((status = ANY (ARRAY['tersedia'::text, 'dicadangkan'::text, 'diserahkan'::text, 'ditutup'::text])));
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_warna_check CHECK (((warna IS NULL) OR (char_length(warna) <= 50)));
ALTER TABLE ONLY public.handover_schedules ADD CONSTRAINT handover_schedules_lokasi_check CHECK (((char_length(btrim(lokasi)) >= 1) AND (char_length(btrim(lokasi)) <= 200)));
ALTER TABLE ONLY public.handover_schedules ADD CONSTRAINT handover_schedules_status_check CHECK ((status = ANY (ARRAY['terjadwal'::text, 'dibatalkan'::text, 'selesai'::text])));
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_deskripsi_check CHECK (((char_length(btrim(deskripsi)) >= 10) AND (char_length(btrim(deskripsi)) <= 2000)));
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_kategori_check CHECK (((char_length(btrim(kategori)) >= 1) AND (char_length(btrim(kategori)) <= 100)));
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_lokasi_kehilangan_check CHECK (((char_length(btrim(lokasi_kehilangan)) >= 1) AND (char_length(btrim(lokasi_kehilangan)) <= 200)));
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_merek_check CHECK (((merek IS NULL) OR (char_length(merek) <= 100)));
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_status_check CHECK ((status = ANY (ARRAY['aktif'::text, 'ditutup'::text])));
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_warna_check CHECK (((warna IS NULL) OR (char_length(warna) <= 50)));
ALTER TABLE ONLY public.notifications ADD CONSTRAINT notifications_pesan_check CHECK ((char_length(pesan) <= 500));
ALTER TABLE ONLY public.outbox_surel ADD CONSTRAINT outbox_surel_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 4)));
ALTER TABLE ONLY public.outbox_surel ADD CONSTRAINT outbox_surel_status_check CHECK ((status = ANY (ARRAY['menunggu'::text, 'terkirim'::text, 'gagal'::text])));
ALTER TABLE ONLY public.penugasan_admin ADD CONSTRAINT penugasan_admin_status_check CHECK ((status = ANY (ARRAY['aktif'::text, 'dicabut'::text])));
ALTER TABLE ONLY public.penugasan_admin ADD CONSTRAINT penugasan_revoked_check CHECK ((((status = 'aktif'::text) AND (revoked_at IS NULL)) OR ((status = 'dicabut'::text) AND (revoked_at IS NOT NULL))));
ALTER TABLE ONLY public.photos ADD CONSTRAINT photos_one_report_check CHECK ((num_nonnulls(found_id, lost_id) = 1));
ALTER TABLE ONLY public.users ADD CONSTRAINT users_email_check CHECK ((char_length(email) <= 254));
ALTER TABLE ONLY public.users ADD CONSTRAINT users_nama_check CHECK (((char_length(btrim(nama)) >= 1) AND (char_length(btrim(nama)) <= 100)));
ALTER TABLE ONLY public.users ADD CONSTRAINT users_role_check CHECK ((role = ANY (ARRAY['pengguna'::text, 'admin_fakultas'::text, 'admin_pusat'::text])));
ALTER TABLE ONLY public.audit_records ADD CONSTRAINT audit_records_actor_id_fkey FOREIGN KEY (actor_id) REFERENCES public.users(user_id);
ALTER TABLE ONLY public.claims ADD CONSTRAINT claims_decision_by_fkey FOREIGN KEY (decision_by) REFERENCES public.users(user_id);
ALTER TABLE ONLY public.claims ADD CONSTRAINT claims_found_id_fkey FOREIGN KEY (found_id) REFERENCES public.found_reports(found_id);
ALTER TABLE ONLY public.claims ADD CONSTRAINT claims_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(user_id);
ALTER TABLE ONLY public.data_rahasia ADD CONSTRAINT data_rahasia_found_id_fkey FOREIGN KEY (found_id) REFERENCES public.found_reports(found_id) ON DELETE CASCADE;
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_area_id_fkey FOREIGN KEY (area_id) REFERENCES public.areas(area_id);
ALTER TABLE ONLY public.found_reports ADD CONSTRAINT found_reports_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(user_id);
ALTER TABLE ONLY public.handover_schedules ADD CONSTRAINT handover_schedules_claim_id_fkey FOREIGN KEY (claim_id) REFERENCES public.claims(claim_id);
ALTER TABLE ONLY public.handover_schedules ADD CONSTRAINT handover_schedules_dicatat_oleh_admin_id_fkey FOREIGN KEY (dicatat_oleh_admin_id) REFERENCES public.users(user_id);
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_area_id_fkey FOREIGN KEY (area_id) REFERENCES public.areas(area_id);
ALTER TABLE ONLY public.lost_reports ADD CONSTRAINT lost_reports_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(user_id);
ALTER TABLE ONLY public.notifications ADD CONSTRAINT notifications_user_id_fkey FOREIGN KEY (user_id) REFERENCES public.users(user_id) ON DELETE CASCADE;
ALTER TABLE ONLY public.outbox_surel ADD CONSTRAINT outbox_surel_notification_id_fkey FOREIGN KEY (notification_id) REFERENCES public.notifications(notification_id) ON DELETE SET NULL;
ALTER TABLE ONLY public.penugasan_admin ADD CONSTRAINT penugasan_admin_admin_id_fkey FOREIGN KEY (admin_id) REFERENCES public.users(user_id);
ALTER TABLE ONLY public.penugasan_admin ADD CONSTRAINT penugasan_admin_area_id_fkey FOREIGN KEY (area_id) REFERENCES public.areas(area_id);
ALTER TABLE ONLY public.photos ADD CONSTRAINT photos_found_id_fkey FOREIGN KEY (found_id) REFERENCES public.found_reports(found_id) ON DELETE CASCADE;
ALTER TABLE ONLY public.photos ADD CONSTRAINT photos_lost_id_fkey FOREIGN KEY (lost_id) REFERENCES public.lost_reports(lost_id) ON DELETE CASCADE;
ALTER TABLE ONLY public.users ADD CONSTRAINT users_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE;

commit;